package engine;
import java.util.*;
public final class Checker {
 static final Set<Integer> OUTER=Set.of(17,22,46,51,131,212,347);
 static final Set<Integer> BOTH=Set.of(15,39,49,77,78);
 static List<Object> sorted(Object o,boolean inner){List<Object>a=new ArrayList<>();for(Object x:Json.list(o)){if(inner&&x instanceof List<?>)a.add(sorted(x,false));else a.add(x);}a.sort(Comparator.comparing(Json::stringify));return a;}
 public static boolean equal(Object a,Object b){if(a==null||b==null)return a==b;if(a instanceof Number x&&b instanceof Number y){if(!(x instanceof Double||x instanceof Float||y instanceof Double||y instanceof Float))return new java.math.BigDecimal(x.toString()).compareTo(new java.math.BigDecimal(y.toString()))==0;double xx=x.doubleValue(),yy=y.doubleValue();if(!Double.isFinite(xx)||!Double.isFinite(yy))return false;return Math.abs(xx-yy)<=1e-6*Math.max(1,Math.abs(yy));}if(a instanceof List<?> x&&b instanceof List<?> y){if(x.size()!=y.size())return false;for(int i=0;i<x.size();i++)if(!equal(x.get(i),y.get(i)))return false;return true;}if(a instanceof Map<?,?> x&&b instanceof Map<?,?> y){if(!x.keySet().equals(y.keySet()))return false;for(Object k:x.keySet())if(!equal(x.get(k),y.get(k)))return false;return true;}return a.equals(b);}
 public static boolean check(int id,List<?> args,Object expected,Object actual){try{
  if(id==1||id==167){List<?> a=(List<?>)args.get(0),v=(List<?>)actual;if(v.size()!=2)return false;int i=Bridge.num(v.get(0))-(id==167?1:0),j=Bridge.num(v.get(1))-(id==167?1:0);return i>=0&&j>=0&&i<a.size()&&j<a.size()&&i!=j&&(long)Bridge.num(a.get(i))+Bridge.num(a.get(j))==Bridge.num(args.get(1));}
  if(id==5){String s=(String)actual;return s.length()==((String)expected).length()&&((String)args.get(0)).contains(s)&&new StringBuilder(s).reverse().toString().equals(s);}
  if(id==76){String s=(String)actual,t=(String)args.get(1);if(((String)expected).isEmpty())return s.isEmpty();if(s.length()!=((String)expected).length()||!((String)args.get(0)).contains(s))return false;Map<Character,Integer> counts=new HashMap<>();for(char c:s.toCharArray())counts.merge(c,1,Integer::sum);for(char c:t.toCharArray())if(counts.merge(c,-1,Integer::sum)<0)return false;return true;}
  if(id==162){List<?>a=(List<?>)args.get(0);int i=Bridge.num(actual);return i>=0&&i<a.size()&&(i==0||Bridge.num(a.get(i))>Bridge.num(a.get(i-1)))&&(i==a.size()-1||Bridge.num(a.get(i))>Bridge.num(a.get(i+1)));}
  if(id==210){int n=Bridge.num(args.get(0));List<?>edges=(List<?>)args.get(1),order=(List<?>)actual;int[] deg=new int[n];List<List<Integer>>adj=new ArrayList<>();for(int i=0;i<n;i++)adj.add(new ArrayList<>());for(Object e:edges){List<?>p=(List<?>)e;int x=Bridge.num(p.get(0)),y=Bridge.num(p.get(1));deg[x]++;adj.get(y).add(x);}Queue<Integer>q=new ArrayDeque<>();for(int i=0;i<n;i++)if(deg[i]==0)q.add(i);int count=0;while(!q.isEmpty()){int u=q.remove();count++;for(int v:adj.get(u))if(--deg[v]==0)q.add(v);}if(count<n)return order.isEmpty();if(order.size()!=n)return false;int[]pos=new int[n];Arrays.fill(pos,-1);for(int i=0;i<n;i++){int v=Bridge.num(order.get(i));if(v<0||v>=n||pos[v]>=0)return false;pos[v]=i;}for(Object e:edges){List<?>p=(List<?>)e;if(pos[Bridge.num(p.get(1))]>=pos[Bridge.num(p.get(0))])return false;}return true;}
  if(id==108){List<?>a=(List<?>)actual,expectedValues=(List<?>)args.get(0);if(a.isEmpty())return expectedValues.isEmpty();int[][]child=new int[a.size()][2];for(int[]c:child)Arrays.fill(c,-1);Queue<Integer>q=new ArrayDeque<>();q.add(0);int k=1;while(!q.isEmpty()&&k<a.size()){int u=q.remove();for(int side=0;side<2&&k<a.size();side++,k++)if(a.get(k)!=null){child[u][side]=k;q.add(k);}}List<Object>in=new ArrayList<>();return balanced(a,child,0,in)>=0&&equal(in,expectedValues);}
  if(id==373){List<?>v=(List<?>)actual,e=(List<?>)expected,a=(List<?>)args.get(0),b=(List<?>)args.get(1);if(v.size()!=e.size())return false;Map<String,Integer>used=new HashMap<>();List<Long>vs=new ArrayList<>(),es=new ArrayList<>();for(Object z:v){List<?>pair=(List<?>)z;if(pair.size()!=2)return false;int x=Bridge.num(pair.get(0)),y=Bridge.num(pair.get(1));long ca=a.stream().filter(t->Bridge.num(t)==x).count(),cb=b.stream().filter(t->Bridge.num(t)==y).count();String key=x+","+y;if(used.merge(key,1,Integer::sum)>ca*cb)return false;vs.add((long)x+y);}for(Object z:e){List<?>pair=(List<?>)z;es.add((long)Bridge.num(pair.get(0))+Bridge.num(pair.get(1)));}Collections.sort(vs);Collections.sort(es);return vs.equals(es);}
  if(OUTER.contains(id))return equal(sorted(expected,false),sorted(actual,false));if(BOTH.contains(id))return equal(sorted(expected,true),sorted(actual,true));return equal(expected,actual);
 }catch(Exception e){return false;}}
 static int balanced(List<?>a,int[][]c,int u,List<Object>out){if(u<0)return 0;int l=balanced(a,c,c[u][0],out);out.add(a.get(u));int r=balanced(a,c,c[u][1],out);if(l<0||r<0||Math.abs(l-r)>1)return -1;return 1+Math.max(l,r);}
}
